def transform_rule(grid):
    h,w=len(grid),len(grid[0])
    squares=[(r,c) for r in range(h-1) for c in range(w-1)
             if grid[r][c]==grid[r][c+1]==grid[r+1][c]==grid[r+1][c+1]==2]
    squares.sort(key=lambda rc:(rc[1],rc[0]))
    out=[row[:] for row in grid]
    n=len(squares)
    for i,(r,c) in enumerate(squares):
        if (n-1-i)%2==0:
            for rr in (r,r+1):
                for cc in (c,c+1):
                    out[rr][cc]=8
    return out
